import { useState, useRef, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import {
  togglePlay,
  nextTrack,
  prevTrack,
  setVolume,
  toggleMute,
  setIsModalOpen,
  setModalPosition,
} from "../../redux/slices/audioSlice";
import tracks from "../../data/tracksData";
import "./TrackModal.css";

function TrackModal() {
  const dispatch = useDispatch();

  const {
    isPlaying,
    volume,
    currentTrackIndex,
    isModalOpen,
    isMuted,
    modalPosition,
  } = useSelector((state) => state.audio);

  const currentTrack = tracks[currentTrackIndex] || tracks[0];

  // Inizializza o recupera la posizione del modale
  const [position, setPosition] = useState(() => {
    if (modalPosition) return modalPosition;
    const defaultX = Math.max(8, Math.min(window.innerWidth - 270, window.innerWidth - 260));
    const defaultY = Math.max(8, Math.min(90, window.innerHeight - 340));
    return { x: defaultX, y: defaultY };
  });

  const isDraggingRef = useRef(false);
  const dragStartRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    if (modalPosition) {
      setPosition(modalPosition);
    }
  }, [modalPosition]);

  useEffect(() => {
    const handleResize = () => {
      setPosition((prev) => {
        const clampedX = Math.min(prev.x, Math.max(10, window.innerWidth - 260));
        const clampedY = Math.min(prev.y, Math.max(10, window.innerHeight - 340));
        return { x: clampedX, y: clampedY };
      });
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  if (!isModalOpen) return null;

  // --- Gestione Drag con Pointer & Touch ---
  const startDrag = (clientX, clientY, target, pointerId = null) => {
    isDraggingRef.current = true;
    dragStartRef.current = {
      x: clientX - position.x,
      y: clientY - position.y,
    };
    if (pointerId !== null && target.setPointerCapture) {
      try {
        target.setPointerCapture(pointerId);
      } catch (e) {}
    }
  };

  const moveDrag = (clientX, clientY) => {
    if (!isDraggingRef.current) return;
    const newX = clientX - dragStartRef.current.x;
    const newY = clientY - dragStartRef.current.y;
    const maxX = window.innerWidth - 250;
    const maxY = window.innerHeight - 320;
    const nextPos = {
      x: Math.max(8, Math.min(newX, maxX)),
      y: Math.max(8, Math.min(newY, maxY)),
    };
    setPosition(nextPos);
    dispatch(setModalPosition(nextPos));
  };

  const endDrag = (target, pointerId = null) => {
    if (isDraggingRef.current) {
      isDraggingRef.current = false;
      if (pointerId !== null && target.releasePointerCapture) {
        try {
          target.releasePointerCapture(pointerId);
        } catch (e) {}
      }
    }
  };

  const handleClose = (e) => {
    e.stopPropagation();
    dispatch(setIsModalOpen(false));
  };

  return (
    <div
      className="track-modal-card shadow-lg"
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
      }}
    >
      {/* Header Modale Compatto con Drag Handle isolato */}
      <div className="track-modal-header d-flex justify-content-between align-items-center py-1 px-2">
        <div
          className="drag-handle d-flex align-items-center gap-1 flex-grow-1 py-1"
          onPointerDown={(e) => startDrag(e.clientX, e.clientY, e.currentTarget, e.pointerId)}
          onPointerMove={(e) => moveDrag(e.clientX, e.clientY)}
          onPointerUp={(e) => endDrag(e.currentTarget, e.pointerId)}
          onTouchStart={(e) => {
            if (e.touches.length === 1) startDrag(e.touches[0].clientX, e.touches[0].clientY, e.currentTarget);
          }}
          onTouchMove={(e) => {
            if (e.touches.length === 1 && isDraggingRef.current) moveDrag(e.touches[0].clientX, e.touches[0].clientY);
          }}
          onTouchEnd={(e) => endDrag(e.currentTarget)}
        >
          <i className="bi bi-grip-horizontal text-secondary fs-6"></i>
          <span className="fw-semibold track-header-title">Vinco Eventi Player</span>
        </div>

        {/* Pulsante Chiudi X con StopPropagation per risposta immediata */}
        <button
          onClick={handleClose}
          onPointerDown={(e) => e.stopPropagation()}
          onTouchStart={(e) => e.stopPropagation()}
          className="btn-close-modal"
          aria-label="Chiudi"
          title="Chiudi"
        >
          <i className="bi bi-x-lg"></i>
        </button>
      </div>

      {/* Body del Modale Compatto */}
      <div className="track-modal-body p-2 text-center">
        <div className="cover-wrapper mb-2 mx-auto">
          <img
            src={currentTrack.cover}
            alt={currentTrack.title}
            className="cover-img rounded shadow-sm"
          />
        </div>

        <h6 className="track-title mb-0 fw-bold text-truncate" title={currentTrack.title}>
          {currentTrack.title}
        </h6>
        <p className="track-artist mb-2 text-muted small text-truncate">
          {currentTrack.artist}
        </p>

        {/* Controlli di Riproduzione Compatti */}
        <div className="modal-controls d-flex justify-content-center align-items-center gap-2 mb-2">
          <button
            onClick={() => dispatch(prevTrack(tracks.length))}
            className="btn-modal-ctrl"
            title="Traccia precedente"
            aria-label="Traccia precedente"
          >
            <i className="bi bi-skip-start-fill fs-5"></i>
          </button>

          <button
            onClick={() => dispatch(togglePlay())}
            className="btn-modal-play shadow-sm"
            title={isPlaying ? "Pausa" : "Riproduci"}
            aria-label={isPlaying ? "Pausa" : "Riproduci"}
          >
            <i
              className={`bi ${
                isPlaying ? "bi-pause-fill" : "bi-play-fill"
              } fs-4`}
            ></i>
          </button>

          <button
            onClick={() => dispatch(nextTrack(tracks.length))}
            className="btn-modal-ctrl"
            title="Traccia successiva"
            aria-label="Traccia successiva"
          >
            <i className="bi bi-skip-end-fill fs-5"></i>
          </button>
        </div>

        {/* Controllo Volume Compatto */}
        <div className="modal-volume-control d-flex align-items-center gap-1 px-1">
          <button
            onClick={() => dispatch(toggleMute())}
            className="btn-volume-icon p-0 border-0 bg-transparent text-secondary"
            title={isMuted || volume === 0 ? "Attiva audio" : "Muto"}
            aria-label="Disattiva/Attiva audio"
          >
            <i
              className={`bi ${
                isMuted || volume === 0
                  ? "bi-volume-mute-fill text-danger"
                  : volume < 0.5
                  ? "bi-volume-down-fill"
                  : "bi-volume-up-fill"
              } fs-6`}
            ></i>
          </button>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={isMuted ? 0 : volume}
            onChange={(e) => dispatch(setVolume(parseFloat(e.target.value)))}
            className="form-range volume-range flex-grow-1"
          />
          <span className="volume-percent extra-small fw-semibold text-muted">
            {isMuted ? "0%" : `${Math.round(volume * 100)}%`}
          </span>
        </div>
      </div>
    </div>
  );
}

export default TrackModal;

import { useState, useRef } from "react";
import { useSelector } from "react-redux";
import { Modal, Button, Spinner, Alert, Dropdown } from "react-bootstrap";
import API_BASE_URL from "../../config/api";
import { translations } from "../../utils/translations";
import "./ContactForm.css";

export const COUNTRY_PREFIXES = [
  { code: "it", name: "Italia", prefix: "+39", flagUrl: "https://flagcdn.com/w40/it.png" },
  { code: "fr", name: "Francia", prefix: "+33", flagUrl: "https://flagcdn.com/w40/fr.png" },
  { code: "de", name: "Germania", prefix: "+49", flagUrl: "https://flagcdn.com/w40/de.png" },
  { code: "gb", name: "Regno Unito", prefix: "+44", flagUrl: "https://flagcdn.com/w40/gb.png" },
  { code: "es", name: "Spagna", prefix: "+34", flagUrl: "https://flagcdn.com/w40/es.png" },
  { code: "ch", name: "Svizzera", prefix: "+41", flagUrl: "https://flagcdn.com/w40/ch.png" },
  { code: "at", name: "Austria", prefix: "+43", flagUrl: "https://flagcdn.com/w40/at.png" },
  { code: "us", name: "Stati Uniti / Canada", prefix: "+1", flagUrl: "https://flagcdn.com/w40/us.png" },
  { code: "cn", name: "Cina", prefix: "+86", flagUrl: "https://flagcdn.com/w40/cn.png" },
  { code: "jp", name: "Giappone", prefix: "+81", flagUrl: "https://flagcdn.com/w40/jp.png" },
  { code: "br", name: "Brasile", prefix: "+55", flagUrl: "https://flagcdn.com/w40/br.png" },
];

const initialFormState = {
  nome: "",
  cognome: "",
  email: "",
  prefissoTelefono: "+39",
  telefono: "",
  tipoEvento: "",
  dataEvento: "",
  luogoEvento: "",
  numeroOspiti: "",
  momentoGiornata: "",
  tipoCerimonia: "",
  ideaFesta: "",
  ulterioriInfo: "",
  budget: "",
  accettaTermini: false,
};

// Valida Email
const isValidEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());

// Valida Telefono (almeno 6 cifre numeriche)
const isValidPhone = (phone) => {
  if (!phone) return false;
  const digitsOnly = phone.replace(/[^\d]/g, "");
  return digitsOnly.length >= 6 && digitsOnly.length <= 15;
};

// Valida Data (deve essere da oggi in poi)
const isValidFutureDate = (dateString) => {
  if (!dateString) return false;
  const selectedDate = new Date(dateString);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return selectedDate >= today;
};

// Valida Luogo Evento (deve contenere la virgola per separare luogo e località: es. Masseria Coccaro, Monopoli)
const isValidLocation = (location) => {
  if (!location) return false;
  const parts = location.split(",");
  return parts.length >= 2 && parts[0].trim().length > 0 && parts[1].trim().length > 0;
};


function ContactForm() {
  const formRef = useRef(null);
  const lang = useSelector((state) => state.ui.language);
  const t = translations[lang]?.contactForm || translations.it.contactForm;

  const [formData, setFormData] = useState(initialFormState);
  const [validated, setValidated] = useState(false);
  const [showValidationBanner, setShowValidationBanner] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null); // { type: 'success' | 'danger', message: string }
  const [showResetModal, setShowResetModal] = useState(false);

  const selectedCountry = COUNTRY_PREFIXES.find(
    (c) => c.prefix === formData.prefissoTelefono
  ) || COUNTRY_PREFIXES[0];

  const getCountryName = (country) => {
    return t.countries?.[country.code] || country.name;
  };

  const selectedCountryName = getCountryName(selectedCountry);

  const scrollToTop = () => {
    if (formRef.current) {
      formRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };


  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));

    // If changing tipoEvento to something other than Matrimonio, clear tipoCerimonia
    if (name === "tipoEvento" && value !== "Matrimonio") {
      setFormData((prev) => ({ ...prev, tipoCerimonia: "" }));
    }
  };

  const isFormValid = () => {
    const basicFields = [
      "nome",
      "cognome",
      "tipoEvento",
      "momentoGiornata",
      "budget",
    ];

    const allBasicFilled = basicFields.every(
      (field) => formData[field].toString().trim() !== ""
    );

    const emailOk = isValidEmail(formData.email);
    const phoneOk = isValidPhone(formData.telefono);
    const locationOk = isValidLocation(formData.luogoEvento);
    const guestsOk = Number(formData.numeroOspiti) > 0;
    const dateOk = isValidFutureDate(formData.dataEvento);

    return (
      allBasicFilled &&
      emailOk &&
      phoneOk &&
      locationOk &&
      guestsOk &&
      dateOk &&
      formData.accettaTermini
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setValidated(true);

    if (!isFormValid()) {
      setShowValidationBanner(true);
      scrollToTop();
      return;
    }

    setShowValidationBanner(false);
    setIsSubmitting(true);
    setSubmitStatus(null);

    const cleanPhoneDigits = formData.telefono.trim().replace(/^\+\d{1,4}\s*/, "");
    const fullPhone = `${formData.prefissoTelefono} ${cleanPhoneDigits}`;

    const payload = {
      nome: formData.nome,
      cognome: formData.cognome,
      email: formData.email,
      telefono: fullPhone,
      dataEvento: formData.dataEvento || null,
      tipoEvento: formData.tipoEvento,
      location: formData.luogoEvento,
      numeroOspiti: String(formData.numeroOspiti),
      orarioGiornata: formData.momentoGiornata,
      tipoCerimonia: formData.tipoCerimonia,
      messaggio: formData.ideaFesta
        ? `${formData.ideaFesta}${formData.ulterioriInfo ? "\n\nInfo aggiuntive: " + formData.ulterioriInfo : ""}`
        : formData.ulterioriInfo || "",
      budget: formData.budget,
    };

    try {
      const response = await fetch(`${API_BASE_URL}/api/quotes`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        setSubmitStatus({
          type: "success",
          message: t.successMessage,
        });
        resetFormInputs();
      } else {
        throw new Error("Server error status: " + response.status);
      }
    } catch (error) {
      // Se l'errore è stato lanciato da noi (status 4xx/5xx), mostralo come errore reale
      if (error.message && error.message.startsWith("Server error status:")) {
        setSubmitStatus({
          type: "danger",
          message: t.errorMessage || "Errore nel salvataggio. Riprova più tardi.",
        });
      } else {
        // Errore di rete (backend non raggiungibile) — fallback per demo
        console.warn(
          "Spring Boot backend non raggiungibile. Mostro esito di demo...",
          error
        );
        await new Promise((resolve) => setTimeout(resolve, 800));
        setSubmitStatus({
          type: "success",
          message: t.successMessage,
        });
        resetFormInputs();
      }
    } finally {
      setIsSubmitting(false);
      scrollToTop();
    }
  };

  const resetFormInputs = () => {
    setFormData(initialFormState);
    setValidated(false);
    setShowValidationBanner(false);
  };

  const handleConfirmReset = () => {
    resetFormInputs();
    setShowResetModal(false);
    setSubmitStatus(null);
    scrollToTop();
  };

  return (
    <div ref={formRef} className="contact-form-wrapper p-4 p-md-5 rounded-4 shadow-lg border">
      <div className="mb-4 text-center text-md-start">
        <h2 className="display-6 font-heading fw-bold text-body mb-2">
          {t.title}
        </h2>
        <p className="font-body text-body-secondary fs-6 mb-0">{t.subtitle}</p>
      </div>

      {submitStatus && (
        <Alert
          variant={submitStatus.type}
          dismissible
          onClose={() => setSubmitStatus(null)}
          className="mb-4 rounded-3"
        >
          <i
            className={`bi ${
              submitStatus.type === "success"
                ? "bi-check-circle-fill"
                : "bi-exclamation-triangle-fill"
            } me-2`}
          ></i>
          {submitStatus.message}
        </Alert>
      )}

      {showValidationBanner && (
        <Alert
          variant="warning"
          dismissible
          onClose={() => setShowValidationBanner(false)}
          className="mb-4 rounded-3 fw-medium fs-6"
        >
          <i className="bi bi-info-circle-fill me-2 fs-5"></i>
          {t.validationBanner}
        </Alert>
      )}

      <form onSubmit={handleSubmit} noValidate>
        {/* Row 1: Nome e Cognome */}
        <div className="row g-3 mb-3">
          <div className="col-12 col-md-6">
            <label htmlFor="nome" className="form-label font-body fw-semibold text-body fs-7">
              {t.firstName} <span className="text-danger">*</span>
            </label>
            <input
              type="text"
              id="nome"
              name="nome"
              tabIndex={1}
              value={formData.nome}
              onChange={handleChange}
              placeholder="Es. Mario"
              className={`form-control font-body ${
                validated && !formData.nome.trim() ? "is-invalid" : ""
              }`}
              required
            />
            <div className="invalid-feedback">{t.firstName} è obbligatorio.</div>
          </div>

          <div className="col-12 col-md-6">
            <label htmlFor="cognome" className="form-label font-body fw-semibold text-body fs-7">
              {t.lastName} <span className="text-danger">*</span>
            </label>
            <input
              type="text"
              id="cognome"
              name="cognome"
              tabIndex={2}
              value={formData.cognome}
              onChange={handleChange}
              placeholder="Es. Rossi"
              className={`form-control font-body ${
                validated && !formData.cognome.trim() ? "is-invalid" : ""
              }`}
              required
            />
            <div className="invalid-feedback">{t.lastName} è obbligatorio.</div>
          </div>
        </div>

        {/* Row 2: Email e Telefono */}
        <div className="row g-3 mb-3">
          <div className="col-12 col-md-6">
            <label htmlFor="email" className="form-label font-body fw-semibold text-body fs-7">
              {t.email} <span className="text-danger">*</span>
            </label>
            <input
              type="email"
              id="email"
              name="email"
              tabIndex={3}
              value={formData.email}
              onChange={handleChange}
              placeholder="mario.rossi@example.com"
              className={`form-control font-body ${
                validated && !isValidEmail(formData.email) ? "is-invalid" : ""
              }`}
              required
            />
            <div className="invalid-feedback">Inserisci una {t.email} valida.</div>
          </div>

          <div className="col-12 col-md-6">
            <label htmlFor="telefono" className="form-label font-body fw-semibold text-body fs-7">
              {t.phone} <span className="text-danger">*</span>
            </label>
            <div className="input-group">
              <Dropdown className="phone-prefix-dropdown">
                <Dropdown.Toggle
                  variant="outline-secondary"
                  id="dropdown-phone-prefix"
                  className="d-flex align-items-center gap-1 phone-prefix-btn"
                  title={`${selectedCountryName} (${selectedCountry.prefix})`}
                >
                  <img
                    src={selectedCountry.flagUrl}
                    alt={selectedCountryName}
                    className="country-flag-icon"
                    width="18"
                    height="13"
                  />
                  <span className="prefix-num-sm">{selectedCountry.prefix}</span>
                </Dropdown.Toggle>

                <Dropdown.Menu className="phone-prefix-menu shadow-lg">
                  {COUNTRY_PREFIXES.map((country) => {
                    const countryName = getCountryName(country);
                    return (
                      <Dropdown.Item
                        key={country.code}
                        active={country.prefix === formData.prefissoTelefono}
                        onClick={() => setFormData((prev) => ({ ...prev, prefissoTelefono: country.prefix }))}
                        className="d-flex align-items-center gap-2 py-2 px-3 fs-7"
                      >
                        <img
                          src={country.flagUrl}
                          alt={countryName}
                          className="country-flag-icon"
                          width="18"
                          height="13"
                        />
                        <span className="fw-semibold me-auto">{countryName}</span>
                        <span className="text-body-secondary font-monospace small">{country.prefix}</span>
                      </Dropdown.Item>
                    );
                  })}
                </Dropdown.Menu>
              </Dropdown>

              <input
                type="tel"
                id="telefono"
                name="telefono"
                tabIndex={5}
                value={formData.telefono}
                onChange={handleChange}
                placeholder="333 123 4567"
                className={`form-control phone-input-field font-body ${
                  validated && !isValidPhone(formData.telefono) ? "is-invalid" : ""
                }`}
                required
              />
              <div className="invalid-feedback">Il {t.phone} è obbligatorio (inserisci un numero di almeno 6 cifre).</div>
            </div>
          </div>
        </div>

        {/* Row 3: Tipo Evento e Data Evento */}
        <div className="row g-3 mb-3">
          <div className="col-12 col-md-6">
            <label htmlFor="tipoEvento" className="form-label font-body fw-semibold text-body fs-7">
              {t.eventType} <span className="text-danger">*</span>
            </label>
            <select
              id="tipoEvento"
              name="tipoEvento"
              tabIndex={5}
              value={formData.tipoEvento}
              onChange={handleChange}
              className={`form-select font-body ${
                validated && !formData.tipoEvento ? "is-invalid" : ""
              }`}
              required
            >
              <option value="">{t.selectEventType}</option>
              <option value="Matrimonio">{t.eventTypes.wedding}</option>
              <option value="Evento Aziendale">{t.eventTypes.corporate}</option>
              <option value="Evento privato">{t.eventTypes.private}</option>
              <option value="Altro">{t.eventTypes.other}</option>
            </select>
            <div className="invalid-feedback">Seleziona il {t.eventType}.</div>
          </div>

          <div className="col-12 col-md-6">
            <label htmlFor="dataEvento" className="form-label font-body fw-semibold text-body fs-7">
              {t.eventDate} <span className="text-danger">*</span>
            </label>
            <input
              type="date"
              id="dataEvento"
              name="dataEvento"
              tabIndex={6}
              min={new Date().toISOString().split("T")[0]}
              value={formData.dataEvento}
              onChange={handleChange}
              className={`form-control font-body ${
                validated && !isValidFutureDate(formData.dataEvento)
                  ? "is-invalid"
                  : ""
              }`}
              required
            />
            <div className="invalid-feedback">La {t.eventDate} è obbligatoria.</div>
          </div>
        </div>

        {/* Row 4: Luogo Evento e Numero di ospiti */}
        <div className="row g-3 mb-3">
          <div className="col-12 col-md-6">
            <label htmlFor="luogoEvento" className="form-label font-body fw-semibold text-body fs-7">
              {t.eventLocation} <span className="text-danger">*</span>
            </label>

            <div className="position-relative">
              {validated && !isValidLocation(formData.luogoEvento) && (
                <div className="location-fumetto-speech-bubble" role="alert">
                  <i className="bi bi-info-circle-fill me-2 text-warning fs-6"></i>
                  <span>
                    {t.locationFumettoHint ||
                      "Inserisci sia il Luogo che la Località separati da una virgola (es. Masseria Coccaro, Monopoli)"}
                  </span>
                </div>
              )}

              <input
                type="text"
                id="luogoEvento"
                name="luogoEvento"
                tabIndex={7}
                value={formData.luogoEvento}
                onChange={handleChange}
                placeholder={t.eventLocationPlaceholder || "Es. Masseria Coccaro, Monopoli"}
                className={`form-control font-body ${
                  validated && !isValidLocation(formData.luogoEvento) ? "is-invalid" : ""
                }`}
                required
              />
            </div>
            <div className="invalid-feedback">
              {t.locationInvalidError ||
                "Inserisci il Luogo e la Località separati da una virgola (es. Masseria Coccaro, Monopoli)."}
            </div>
          </div>

          <div className="col-12 col-md-6">
            <label htmlFor="numeroOspiti" className="form-label font-body fw-semibold text-body fs-7">
              {t.guestsCount} <span className="text-danger">*</span>
            </label>
            <input
              type="number"
              id="numeroOspiti"
              name="numeroOspiti"
              tabIndex={8}
              min="1"
              value={formData.numeroOspiti}
              onChange={handleChange}
              placeholder="Es. 120"
              className={`form-control font-body ${
                validated &&
                (!formData.numeroOspiti || Number(formData.numeroOspiti) <= 0)
                  ? "is-invalid"
                  : ""
              }`}
              required
            />
            <div className="invalid-feedback">Inserisci il {t.guestsCount}.</div>
          </div>
        </div>

        {/* Row 5: Momento Giornata (Pranzo/Cena) e Tipo Cerimonia (se Matrimonio) */}
        <div className="row g-3 mb-3">
          <div className={`col-12 ${formData.tipoEvento === "Matrimonio" ? "col-md-6" : "col-md-12"}`}>
            <label htmlFor="momentoGiornata" className="form-label font-body fw-semibold text-body fs-7">
              {t.timeOfDay} <span className="text-danger">*</span>
            </label>
            <select
              id="momentoGiornata"
              name="momentoGiornata"
              tabIndex={9}
              value={formData.momentoGiornata}
              onChange={handleChange}
              className={`form-select font-body ${
                validated && !formData.momentoGiornata ? "is-invalid" : ""
              }`}
              required
            >
              <option value="">{t.selectTimeOfDay}</option>
              <option value="Pranzo">{t.timeOfDayOptions.lunch}</option>
              <option value="Cena">{t.timeOfDayOptions.dinner}</option>
            </select>
            <div className="invalid-feedback">Seleziona il momento della giornata.</div>
          </div>

          {formData.tipoEvento === "Matrimonio" && (
            <div className="col-12 col-md-6">
              <label htmlFor="tipoCerimonia" className="form-label font-body fw-semibold text-body fs-7">
                {t.ceremonyType} <span className="text-body-secondary fw-normal">{t.optional}</span>
              </label>
              <select
                id="tipoCerimonia"
                name="tipoCerimonia"
                tabIndex={10}
                value={formData.tipoCerimonia}
                onChange={handleChange}
                className="form-select font-body"
              >
                <option value="">{t.selectCeremonyType}</option>
                <option value="Civile">{t.ceremonyOptions.civil}</option>
                <option value="Religioso">{t.ceremonyOptions.religious}</option>
                <option value="Altro">{t.ceremonyOptions.other}</option>
              </select>
            </div>
          )}
        </div>

        {/* Row 6: Idea Festa (Textarea) */}
        <div className="mb-3">
          <label htmlFor="ideaFesta" className="form-label font-body fw-semibold text-body fs-7">
            {t.partyIdea} <span className="text-body-secondary fw-normal">{t.optional}</span>
          </label>
          <textarea
            id="ideaFesta"
            name="ideaFesta"
            tabIndex={11}
            rows="3"
            value={formData.ideaFesta}
            onChange={handleChange}
            placeholder="Descrivi come immagini la musica e l'atmosfera per il tuo evento..."
            className="form-control font-body"
          ></textarea>
        </div>

        {/* Row 7: Ulteriori informazioni (Textarea) */}
        <div className="mb-3">
          <label htmlFor="ulterioriInfo" className="form-label font-body fw-semibold text-body fs-7">
            {t.additionalInfo} <span className="text-body-secondary fw-normal">{t.optional}</span>
          </label>
          <textarea
            id="ulterioriInfo"
            name="ulterioriInfo"
            tabIndex={12}
            rows="2"
            value={formData.ulterioriInfo}
            onChange={handleChange}
            placeholder="Note aggiuntive, dettagli sulla location, esigenze particolari..."
            className="form-control font-body"
          ></textarea>
        </div>

        {/* Row 8: Budget (Select) */}
        <div className="mb-4">
          <label htmlFor="budget" className="form-label font-body fw-semibold text-body fs-7">
            {t.budget} <span className="text-danger">*</span>
          </label>
          <select
            id="budget"
            name="budget"
            tabIndex={13}
            value={formData.budget}
            onChange={handleChange}
            className={`form-select font-body ${
              validated && !formData.budget ? "is-invalid" : ""
            }`}
            required
          >
            <option value="">{t.selectBudget}</option>
            <option value="1.500€-3.000€">{t.budgetOptions.tier1}</option>
            <option value="3.000€-5.000€">{t.budgetOptions.tier2}</option>
            <option value="+5.000€">{t.budgetOptions.tier3}</option>
          </select>
          <div className="invalid-feedback">Seleziona una fascia di budget.</div>
        </div>

        {/* Row 9: Checkbox Termini e Condizioni */}
        <div className="mb-4 form-check">
          <input
            type="checkbox"
            id="accettaTermini"
            name="accettaTermini"
            tabIndex={14}
            checked={formData.accettaTermini}
            onChange={handleChange}
            className={`form-check-input ${
              validated && !formData.accettaTermini ? "is-invalid" : ""
            }`}
            required
          />
          <label htmlFor="accettaTermini" className="form-check-label font-body fs-7 text-body">
            {t.acceptTerms} <span className="text-danger">*</span>
          </label>
          <div className="invalid-feedback">
            Devi accettare i termini e le condizioni per proseguire.
          </div>
        </div>

        {/* Row 10: Action Buttons */}
        <div className="d-flex flex-column flex-sm-row gap-3 pt-2">
          <button
            type="submit"
            tabIndex={15}
            disabled={isSubmitting}
            className="btn btn-forest flex-grow-1 py-3 font-body fw-bold d-flex align-items-center justify-content-center gap-2 rounded-3 shadow-sm"
          >
            {isSubmitting ? (
              <>
                <Spinner animation="border" size="sm" role="status" aria-hidden="true" />
                <span>Invio in corso...</span>
              </>
            ) : (
              <>
                <i className="bi bi-send-fill"></i>
                <span>{t.submitBtn}</span>
              </>
            )}
          </button>

          <button
            type="button"
            tabIndex={16}
            disabled={isSubmitting}
            onClick={() => setShowResetModal(true)}
            className="btn btn-outline-secondary py-3 px-4 font-body fw-semibold rounded-3 d-flex align-items-center justify-content-center gap-2"
          >
            <i className="bi bi-arrow-counterclockwise"></i>
            <span>{t.resetBtn}</span>
          </button>
        </div>
      </form>

      {/* Modal di Conferma Reset */}
      <Modal
        show={showResetModal}
        onHide={() => setShowResetModal(false)}
        centered
        backdrop="static"
        className="reset-confirmation-modal"
      >
        <Modal.Header closeButton className="border-0 pb-0">
          <Modal.Title className="font-heading fw-bold h5 text-body">
            <i className="bi bi-exclamation-circle text-warning me-2"></i>
            {t.resetModalTitle}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className="font-body text-body-secondary py-3">
          {t.resetModalText}
        </Modal.Body>
        <Modal.Footer className="border-0 pt-0 d-flex justify-content-end gap-2">
          <Button
            variant="secondary"
            onClick={() => setShowResetModal(false)}
            className="font-body fw-medium rounded-2"
          >
            {t.cancel}
          </Button>
          <Button
            variant="danger"
            onClick={handleConfirmReset}
            className="font-body fw-semibold rounded-2"
          >
            {t.confirmReset}
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}

export default ContactForm;

import { useState, useEffect } from "react";
import { Container, Row, Col, Carousel, Nav, Modal } from "react-bootstrap";
import { useSelector } from "react-redux";
import { translations } from "../../utils/translations";
import { galleryItems as staticGalleryItems } from "./galleryData";
import { getOptimizedCloudinaryUrl } from "../../utils/cloudinary";
import API_BASE_URL from "../../config/api";
import MediaModal from "../MediaModal/MediaModal";
import "./GallerySection.css";

function GallerySection() {
  const lang = useSelector((state) => state.ui.language);
  const { isAuthenticated, token } = useSelector((state) => state.auth);
  const t = translations[lang].gallery;

  const [dbItems, setDbItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [activeFilter, setActiveFilter] = useState("all");

  // Lightbox Modal State
  const [modalShow, setModalShow] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);

  // Admin CRUD Modal State
  const [showAdminModal, setShowAdminModal] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [uploadingMedia, setUploadingMedia] = useState(false);

  const [formData, setFormData] = useState({
    titleIta: "",
    titleEng: "",
    subtitleIta: "",
    subtitleEng: "",
    type: "image",
    src: "",
    category: "djset",
    featured: false,
    startTime: "",
    displayOrder: 1,
    publicId: "",
    posterUrl: "",
  });

  const fetchGalleryItems = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/gallery`);
      if (response.ok) {
        const data = await response.json();
        setDbItems(data);
      }
    } catch (err) {
      console.log("Database gallery non raggiungibile. Uso fallback locali per visualizzazione.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGalleryItems();
  }, []);

  // Formatta l'elenco dei media da renderizzare
  const rawList = dbItems.length > 0 ? dbItems : staticGalleryItems;

  const getItemSrc = (item) => {
    // DB items hanno sempre URL Cloudinary (https://...)
    if (item.src && item.src.startsWith("http")) {
      return item.src;
    }
    // Fallback: cerca nella lista statica per ID
    const staticMatch = staticGalleryItems.find((s) => s.id === item.id);
    return staticMatch ? staticMatch.src : item.src;
  };

  const allItems = rawList.map((item) => {
    const isEng = lang === "en";
    return {
      ...item,
      src: getItemSrc(item),
      title: isEng ? item.titleEng || item.titleIta || item.title : item.titleIta || item.title,
      subtitle: isEng ? item.subtitleEng || item.subtitleIta || item.subtitle : item.subtitleIta || item.subtitle,
    };
  });

  // Filter items based on active tab
  const filteredItems = allItems.filter((item) => {
    if (activeFilter === "photos") return item.type === "image";
    if (activeFilter === "videos") return item.type === "video";
    return true;
  });

  // Featured items for top carousel
  const featuredItems = allItems.filter((item) => item.featured);

  const handleCardClick = (index) => {
    setSelectedIndex(index);
    setModalShow(true);
  };

  const handleCarouselClick = (item) => {
    const foundIndex = filteredItems.findIndex((fi) => fi.id === item.id);
    if (foundIndex !== -1) {
      setSelectedIndex(foundIndex);
    } else {
      setActiveFilter("all");
      const indexInAll = allItems.findIndex((gi) => gi.id === item.id);
      setSelectedIndex(indexInAll >= 0 ? indexInAll : 0);
    }
    setModalShow(true);
  };

  // Handlers Admin CRUD
  const handleOpenCreateModal = () => {
    setEditingItem(null);
    setFormData({
      titleIta: "",
      titleEng: "",
      subtitleIta: "",
      subtitleEng: "",
      type: "image",
      src: "",
      category: "djset",
      featured: false,
      startTime: "",
      displayOrder: allItems.length + 1,
      publicId: "",
      posterUrl: "",
    });
    setShowAdminModal(true);
  };

  const handleOpenEditModal = (e, item) => {
    e.stopPropagation();
    setEditingItem(item);
    setFormData({
      titleIta: item.titleIta || item.title || "",
      titleEng: item.titleEng || item.title || "",
      subtitleIta: item.subtitleIta || item.subtitle || "",
      subtitleEng: item.subtitleEng || item.subtitle || "",
      type: item.type || "image",
      src: item.src || "",
      category: item.category || "djset",
      featured: item.featured || false,
      startTime: item.startTime !== null && item.startTime !== undefined ? item.startTime : "",
      displayOrder: item.displayOrder || 1,
      publicId: item.publicId || "",
      posterUrl: item.posterUrl || "",
    });
    setShowAdminModal(true);
  };

  const handleMediaUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploadingMedia(true);
    const uploadData = new FormData();
    uploadData.append("file", file);

    try {
      const res = await fetch(`${API_BASE_URL}/api/admin/gallery/upload-media`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: uploadData,
      });

      if (res.ok) {
        const data = await res.json();
        setFormData((prev) => ({
          ...prev,
          src: data.url,
          publicId: data.publicId || prev.publicId,
          posterUrl: data.posterUrl || prev.posterUrl,
        }));
        alert("File multimediale caricato su Cloudinary con successo!");
      } else {
        alert("Errore durante l'upload del file su Cloudinary.");
      }
    } catch (err) {
      alert("Errore di connessione durante l'upload multimediale.");
    } finally {
      setUploadingMedia(false);
    }
  };

  const handleCreateOrUpdate = async (e) => {
    e.preventDefault();

    if (!formData.src) {
      alert("Inserisci un URL o carica un file multimediale prima di salvare.");
      return;
    }

    const payload = {
      ...formData,
      startTime: formData.startTime !== "" ? parseFloat(formData.startTime) : null,
      displayOrder: parseInt(formData.displayOrder) || 1,
    };

    try {
      const isEdit = editingItem && editingItem.id && !String(editingItem.id).startsWith("v_") && !String(editingItem.id).startsWith("p_") && !String(editingItem.id).startsWith("v1");
      const url = isEdit
        ? `${API_BASE_URL}/api/admin/gallery/${editingItem.id}`
        : `${API_BASE_URL}/api/admin/gallery`;
      const method = isEdit ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        setShowAdminModal(false);
        setEditingItem(null);
        fetchGalleryItems();
      } else {
        alert("Errore nel salvataggio dell'elemento della galleria.");
      }
    } catch (err) {
      alert("Errore di connessione con il server backend.");
    }
  };

  const handleDeleteItem = async (e, id) => {
    e.stopPropagation();
    if (!window.confirm(t.confirmDeleteMedia)) return;

    try {
      const response = await fetch(`${API_BASE_URL}/api/admin/gallery/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      if (response.ok) {
        fetchGalleryItems();
      } else {
        alert("Impossibile eliminare l'elemento selezionato.");
      }
    } catch (err) {
      alert("Errore di connessione durante l'eliminazione.");
    }
  };

  return (
    <section className="gallery-section py-5">
      <Container>
        {/* Admin Action Control Bar */}
        {isAuthenticated && (
          <div className="bg-success-subtle border border-success border-opacity-25 p-3 rounded-4 mb-4 d-flex flex-column flex-md-row justify-content-between align-items-center gap-3">
            <span className="fw-bold text-success d-flex align-items-center gap-2">
              <i className="bi bi-shield-lock-fill fs-5"></i>
              {t.adminMode}
            </span>
            <button
              onClick={handleOpenCreateModal}
              className="btn btn-success btn-sm fw-bold d-flex align-items-center gap-2 px-3 py-2 rounded-pill shadow-sm"
            >
              <i className="bi bi-plus-circle-fill"></i>
              <span>{t.addMedia}</span>
            </button>
          </div>
        )}

        {/* Carosello In Evidenza */}
        {featuredItems.length > 0 && (
          <div className="carousel-highlight-container mb-5 p-3 p-md-4 rounded-4 position-relative">
            <div className="text-center mb-4">
              <h2 className="display-6 font-heading fw-bold text-body mb-2">
                {t.carouselTitle}
              </h2>
              <p className="font-body text-body-secondary mb-0 fs-6">
                {t.carouselSubtitle}
              </p>
            </div>

            <Carousel fade interval={4000} className="gallery-top-carousel rounded-4 overflow-hidden shadow">
              {featuredItems.map((item) => (
                <Carousel.Item
                  key={item.id}
                  onClick={() => handleCarouselClick(item)}
                  className="gallery-carousel-item cursor-pointer position-relative"
                >

                  <div className="carousel-media-wrapper">
                    {item.type === "video" ? (
                      <video
                        src={item.startTime ? `${getOptimizedCloudinaryUrl(item.src, { type: "grid" })}#t=${item.startTime}` : getOptimizedCloudinaryUrl(item.src, { type: "grid" })}
                        poster={item.posterUrl || getOptimizedCloudinaryUrl(item.src, { type: "poster" })}
                        muted
                        loop
                        playsInline
                        autoPlay
                        preload="auto"
                        onLoadedMetadata={(e) => {
                          if (item.startTime && e.target) {
                            e.target.currentTime = item.startTime;
                          }
                        }}
                        className="carousel-media-content"
                      />
                    ) : (
                      <img
                        src={getOptimizedCloudinaryUrl(item.src, { type: "grid" })}
                        alt={item.title}
                        className="carousel-media-content"
                      />
                    )}
                    <div className="carousel-overlay-caption p-4">
                      <span className="badge bg-success px-3 py-2 rounded-pill mb-2">
                        {item.type === "video" ? t.videoBadge : t.photoBadge}
                      </span>
                      <h3 className="h3 font-heading text-white mb-1 fw-bold">
                        {item.title}
                      </h3>
                      <p className="text-white-50 fs-6 mb-0">{item.subtitle}</p>
                    </div>
                  </div>
                </Carousel.Item>
              ))}
            </Carousel>
          </div>
        )}

        {/* Section Heading & Filters */}
        <div className="text-center mb-4">
          <h2 className="display-5 font-heading fw-bold text-body mb-3 gallery-title-line">
            {t.sectionTitle}
          </h2>
          <p className="font-body text-body-secondary fs-5 max-w-700 mx-auto">
            {t.sectionSubtitle}
          </p>

          {/* Filter Nav Tabs */}
          <Nav
            activeKey={activeFilter}
            onSelect={(selectedKey) => setActiveFilter(selectedKey)}
            className="gallery-filter-tabs justify-content-center mt-4 gap-2"
          >
            <Nav.Item>
              <Nav.Link eventKey="all" className="filter-btn rounded-pill px-4 py-2">
                <i className="bi bi-grid-fill me-2"></i>
                {t.filterAll} ({allItems.length})
              </Nav.Link>
            </Nav.Item>
            <Nav.Item>
              <Nav.Link eventKey="photos" className="filter-btn rounded-pill px-4 py-2">
                <i className="bi bi-camera-fill me-2"></i>
                {t.filterPhotos} ({allItems.filter((i) => i.type === "image").length})
              </Nav.Link>
            </Nav.Item>
            <Nav.Item>
              <Nav.Link eventKey="videos" className="filter-btn rounded-pill px-4 py-2">
                <i className="bi bi-film me-2"></i>
                {t.filterVideos} ({allItems.filter((i) => i.type === "video").length})
              </Nav.Link>
            </Nav.Item>
          </Nav>
        </div>

        {/* Multimedia Grid */}
        <Row className="g-3 g-md-4">
          {filteredItems.map((item, index) => (
            <Col key={item.id} xs={12} sm={6} md={4} lg={3}>
              <div
                className="gallery-card rounded-4 overflow-hidden position-relative"
                onClick={() => handleCardClick(index)}
              >
                {/* Admin action buttons overlay on card (Top-Right) */}
                {isAuthenticated && (
                  <div
                    className="position-absolute top-0 end-0 p-2 z-3 d-flex gap-1"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <button
                      onClick={(e) => handleOpenEditModal(e, item)}
                      className="btn btn-warning btn-sm py-1 px-2 fw-bold shadow"
                      title={t.editMedia}
                    >
                      <i className="bi bi-pencil-fill"></i>
                    </button>
                    <button
                      onClick={(e) => handleDeleteItem(e, item.id)}
                      className="btn btn-danger btn-sm py-1 px-2 shadow"
                      title={t.deleteMedia}
                    >
                      <i className="bi bi-trash-fill"></i>
                    </button>
                  </div>
                )}

                {/* Media Container */}
                <div className="gallery-media-wrapper">
                  {item.type === "video" ? (
                    <>
                      <video
                        src={item.startTime ? `${getOptimizedCloudinaryUrl(item.src, { type: "grid" })}#t=${item.startTime}` : getOptimizedCloudinaryUrl(item.src, { type: "grid" })}
